        if(reject)reject.onclick=async()=>{const obs=prompt('Motivo del rechazo (opcional):','')||'';if(!confirm('¿Rechazar esta solicitud? No se modificará el vehículo.'))return;busy(reject);if(approve)busy(approve);try{await call('resolveRequest',{id:r.ID_Solicitud,decision:'Rechazada',observaciones:obs});invalidateClientParkingData();toast('Solicitud rechazada.');requests(r.ID_Solicitud)}catch(e){err(e);busy(reject,false);if(approve)busy(approve,false)}};
