// 1.2.12.2 - Inicio propietario alineado visualmente con Resumen ADMIN
async function ownerHome(){
  try{
    const {hs,vs,reqs,incs}=await ownerData();
    const activeCars=vs.filter(v=>v.Estado==='Activo'&&v.Tipo!=='Moto');
    const withSlot=activeCars.filter(v=>['1','2'].includes(String(v.Slot||'')));
    const motos=vs.filter(v=>v.Estado==='Activo'&&v.Tipo==='Moto');
    const pendingReq=reqs.filter(r=>r.Estado==='Pendiente');
    const openInc=incs.filter(r=>(r.Estado||'Abierta')!=='Cerrada');
    const longstay=reqs.filter(r=>r.Tipo==='PERMANENCIA_PROLONGADA'&&r.Estado==='Aprobada');
    const available=Math.max(0,hs.length*2-withSlot.length);
    const card=(value,label,detail='',action='',alert=false)=>`<article class="summary-card ${action?'clickable':''} ${alert?'alert':''}" ${action?`data-owner-summary="${action}"`:''}><b>${esc(value)}</b><span>${esc(label)}</span>${detail?`<small>${esc(detail)}</small>`:''}</article>`;
    $('#main').innerHTML=`<section class="hero"><h1>Inicio</h1><p>Resumen de tus viviendas, vehículos y gestiones.</p></section>
      <section class="summary-section"><div class="head"><h2>Estado general</h2></div><div class="summary-grid">
        ${card(hs.length,hs.length===1?'Vivienda asociada':'Viviendas asociadas','Ver viviendas','housing')}
        ${card(vs.length,'Vehículos registrados',`${withSlot.length} con slot · ${motos.length} moto${motos.length===1?'':'s'}`,'vehicles')}
        ${card(withSlot.length,'Vehículos con slot',`${available} slots libres`,'vehicles-slot')}
        ${card(motos.length,'Motos activas','Control por matrícula','vehicles-moto')}
      </div></section>
      <section class="summary-section"><div class="head"><h2>Pendientes</h2></div><div class="summary-grid">
        ${card(pendingReq.length,'Solicitudes pendientes',`${reqs.length} solicitudes en total`,'requests',pendingReq.length>0)}
        ${card(openInc.length,'Incidencias abiertas',`${incs.length} incidencias asociadas`,'incidents',openInc.length>0)}
        ${card(longstay.length,'Permanencias autorizadas','Solicitudes aprobadas','longstay')}
      </div></section>`;
    document.querySelectorAll('[data-owner-summary]').forEach(el=>el.onclick=()=>{
      const a=el.dataset.ownerSummary;
      if(a==='housing'){go('ownerHousing');return}
      if(a==='vehicles'){delete state.cache.ownerHousingFilter;go('ownerVehicles');return}
      if(a==='vehicles-slot'){state.cache.ownerVehiclePreset={slot:'Con slot'};go('ownerVehicles');return}
      if(a==='vehicles-moto'){state.cache.ownerVehiclePreset={vehicleClass:'Moto'};go('ownerVehicles');return}
      if(a==='requests'){state.cache.ownerNavPreset={view:'ownerRequests',filter:'pending'};go('ownerRequests');return}
      if(a==='incidents'){state.cache.ownerNavPreset={view:'ownerIncidents',filter:'open'};go('ownerIncidents');return}
      if(a==='longstay'){state.cache.ownerNavPreset={view:'ownerRequests',type:'PERMANENCIA_PROLONGADA'};go('ownerRequests')}
    });
  }catch(e){err(e)}
}
window.addEventListener('unhandledrejection',e=>{if(e&&e.reason)err(e.reason instanceof Error?e.reason:new Error(String(e.reason)))});
window.addEventListener('error',e=>{if(e&&e.error)err(e.error)});
init();

// 1.2.13.6 - Control: incidencias abiertas, seguimiento diario y contexto habitual/temporal
function incidentTypesForContext(p){
  const observational=['Vehículo inmovilizado / posible abandono','Estacionamiento o ubicación indebida','Fuga / pérdida de líquidos'],v=p.vehicle||{},status=p.status||'',source=p.source||'Manual',fixed=incidentTypeFromStatus(status);
  if(fixed)return [fixed];
  if(source==='Manual'&&!status)return ['Otro',...observational];
  if(status==='AUTORIZADO'&&v.Tipo==='Moto')return observational;
  if(status==='AUTORIZADO'&&source==='MATRICULA'){
    const out=[];if(v.ID_Vehiculo&&v.QR_Estado==='Activo')out.push('QR no presentado');return [...out,...observational,'Otro'];
  }
  if(status==='AUTORIZADO'&&source==='QR')return ['QR no corresponde con matrícula','Uso indebido',...observational,'Otro'];
  return [...observational,'Otro'];
}

function controlOpenIncidentsMarkup(r){
  const rows=r.openIncidents||[];if(!rows.length)return '';
  return `<section class="control-open-incidents"><h3>Incidencias abiertas (${rows.length})</h3>${rows.map(x=>`<div class="control-open-incident"><div><b>${esc(x.Tipo)}</b>${x.Situacion?`<span class="subtle"> · ${esc(x.Situacion)}</span>`:''}</div><div class="subtle">Abierta ${esc(shortDateTime(x.FechaHora))} · Intentos ${esc(x.Intentos||1)} · Prioridad ${esc(x.Prioridad||'Normal')}</div><div class="actions"><button type="button" class="secondary control-view-incident" data-id="${esc(x.ID_Incidencia)}">Ver incidencia</button>${x.canFollowup?`<button type="button" class="control-follow-incident" data-id="${esc(x.ID_Incidencia)}">Registrar seguimiento</button>`:`<span class="subtle">${x.createdToday?'Creada hoy: seguimiento disponible mañana':x.followedToday?'Seguimiento de hoy ya registrado':''}</span>`}</div></div>`).join('')}</section>`;
}

function controlFollowupForm(r,incident){
  const host=$('#control-body'),v=r.vehicle||{},plate=r.query||r.currentPlate||v.MatriculaHabitual||'';
  document.body.classList.add('incident-entry-mode');
  host.innerHTML=`<form class="card form incident-create-form" id="control-followup-form"><h2 class="wide">Registrar seguimiento</h2><div class="message wide"><b>${esc(incident.Tipo)}</b>${incident.Situacion?` · ${esc(incident.Situacion)}`:''}<br><span class="subtle">Incidencia ${esc(incident.ID_Incidencia)} · intento actual ${esc(incident.Intentos||1)}</span></div><div class="field"><label>Matrícula observada</label><input name="MatriculaObservada" value="${esc(plate)}" required></div><div class="field wide"><label>Observación *</label><textarea name="Observacion" required placeholder="Describe lo observado en este nuevo intento..."></textarea></div><div class="field"><label>Foto / evidencia *</label><input id="follow-photo" type="file" accept="image/*" capture="environment" required></div><input type="hidden" name="Foto"><div class="wide actions"><button type="submit">REGISTRAR SEGUIMIENTO</button><button type="button" class="secondary" id="cancel-followup">Cancelar</button></div></form>`;
  $('#cancel-followup').onclick=()=>{document.body.classList.remove('incident-entry-mode');resultCard(r)};
  $('#follow-photo').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>12*1024*1024){toast('La foto original no puede superar 12 MB.',true);e.target.value='';return}const submit=$('#control-followup-form button[type=submit]');busy(submit);try{const dataUrl=await optimizedImageData(file),out=await call('uploadPhoto',{dataUrl});$('#control-followup-form [name=Foto]').value=out.url;toast('Foto subida.')}catch(x){e.target.value='';$('#control-followup-form [name=Foto]').value='';err(x)}finally{busy(submit,false)}};
  $('#control-followup-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter,data=Object.fromEntries(new FormData(e.target));if(!data.Foto){toast('La fotografía del seguimiento es obligatoria.',true);return}busy(b);try{await call('saveIncidentFollowup',{ids:[incident.ID_Incidencia],Observacion:data.Observacion,Foto:data.Foto,MatriculaObservada:data.MatriculaObservada,OrigenControl:r.source||'MATRICULA',EstadoOrigen:r.status||'',Situacion:incident.Situacion||''});toast('Seguimiento registrado.');document.body.classList.remove('incident-entry-mode');if(r.source==='QR'&&r.vehicle?.QR_Token)lookupQr(r.vehicle.QR_Token);else if(data.MatriculaObservada)resultCard(await call('searchPlate',{plate:data.MatriculaObservada}));else control()}catch(x){toast(x.message,true);busy(b,false)}};
}

function resultCard(r){
  state.scanResult=r;const v=r.vehicle||{},h=r.housing||{},o=r.owner||{},good=r.status==='AUTORIZADO',query=r.query||'',temp=v.MatriculaTemporal&&v.Estado==='Activo'&&r.isTemporary,habitualNotCurrent=r.status==='MATRICULA HABITUAL NO VIGENTE'&&v.MatriculaTemporal,validPlate=temp?v.MatriculaTemporal:habitualNotCurrent?v.MatriculaTemporal:(r.currentPlate||query||v.MatriculaHabitual||''),title=good?'ACCESO AUTORIZADO':r.status;
  $('#control-body').innerHTML=`<article class="card result wide ${good?'':'bad'}"><h2 class="control-result-title">${esc(title)}</h2>${validPlate?`<div class="control-current-label">${habitualNotCurrent?'Matrícula válida actualmente':'Matrícula comprobada'}</div><div class="plate ${good||habitualNotCurrent?'control-valid-plate':''}">${esc(validPlate)}</div>`:''}${habitualNotCurrent?`<div class="message bad"><b>La matrícula habitual ${esc(v.MatriculaHabitual||query)} no está vigente para el acceso.</b><br>Temporal vigente: <b>${esc(v.MatriculaTemporal)}</b>${v.TemporalHasta?` hasta ${esc(dateEs(v.TemporalHasta))}`:''}.</div>`:''}${v.ID_Vehiculo?`<div class="details control-secondary-info"><div><small>Vivienda</small>${esc(housingShort(h))}</div><div><small>Slot</small>${esc(v.Tipo==='Moto'?'No aplica':v.Slot||'Sin slot')}</div><div><small>Tipo</small>${esc(v.Tipo==='Moto'?'Moto':'Vehículo')}</div><div><small>Estado</small>${esc(v.Estado||'—')}</div>${v.MatriculaHabitual?`<div><small>Matrícula habitual</small>${esc(v.MatriculaHabitual)}</div>`:''}${v.MatriculaTemporal?`<div><small>Matrícula temporal</small>${esc(v.MatriculaTemporal)}${v.TemporalHasta?`<span class="subtle ${temp||habitualNotCurrent?'temp-active':''}">Vigente hasta ${esc(dateEs(v.TemporalHasta))}</span>`:''}</div>`:''}${v.Marca||v.Modelo?`<div><small>Marca / modelo</small>${esc([v.Marca,v.Modelo].filter(Boolean).join(' '))}</div>`:''}<div><small>Propietario</small>${esc(o.Nombre||h.Responsable||'—')}</div>${v.Tipo==='Moto'?'':`<div><small>QR</small>${esc(v.QR_Estado||'—')}</div>`}${r.longStay?`<div><small>Permanencia autorizada</small>${esc(dateEs(r.longStay.FechaInicio))} → ${esc(dateEs(r.longStay.FechaFin))}</div>`:''}</div>`:''}${controlOpenIncidentsMarkup(r)}<div class="actions" style="justify-content:center;margin-top:1rem"><button id="incident-result">Registrar nueva incidencia</button><button class="secondary" id="again">Otra consulta</button></div></article>`;
  $('#again').onclick=()=>control();$('#incident-result').onclick=()=>incidentForm(Object.assign({},r,{query:query||validPlate}));
  document.querySelectorAll('.control-view-incident').forEach(b=>b.onclick=()=>incidents(b.dataset.id));
  document.querySelectorAll('.control-follow-incident').forEach(b=>b.onclick=()=>{const i=(r.openIncidents||[]).find(x=>x.ID_Incidencia===b.dataset.id);if(i)controlFollowupForm(r,i)});
}


// 1.2.17.3 - Inicio propietario: accesos con filtros deterministas
async function ownerHome(){
  try{
    const {hs,vs,reqs,incs}=await ownerData();
    const activeCars=vs.filter(v=>v.Estado==='Activo'&&v.Tipo!=='Moto');
    const withSlot=activeCars.filter(v=>['1','2'].includes(String(v.Slot||'')));
    const motos=vs.filter(v=>v.Estado==='Activo'&&v.Tipo==='Moto');
    const pendingReq=reqs.filter(r=>r.Estado==='Pendiente');
    const openInc=incs.filter(r=>(r.Estado||'Abierta')!=='Cerrada');
    const longstay=reqs.filter(r=>r.Tipo==='PERMANENCIA_PROLONGADA'&&r.Estado==='Aprobada');
    const available=Math.max(0,hs.length*2-withSlot.length);
    const card=(value,label,detail='',action='',alert=false)=>`<article class="summary-card ${action?'clickable':''} ${alert?'alert':''}" ${action?`data-owner-summary="${action}"`:''}><b>${esc(value)}</b><span>${esc(label)}</span>${detail?`<small>${esc(detail)}</small>`:''}</article>`;
    $('#main').innerHTML=`<section class="hero"><h1>Inicio</h1><p>Resumen de tus viviendas, vehículos y gestiones.</p></section>
      <section class="summary-section"><div class="head"><h2>Estado general</h2></div><div class="summary-grid">
        ${card(hs.length,hs.length===1?'Vivienda asociada':'Viviendas asociadas','Ver viviendas','housing')}
        ${card(vs.length,'Vehículos registrados',`${withSlot.length} con slot · ${motos.length} moto${motos.length===1?'':'s'}`,'vehicles')}
        ${card(withSlot.length,'Vehículos con slot',`${available} slots libres`,'vehicles-slot')}
        ${card(motos.length,'Motos activas','Control por matrícula','vehicles-moto')}
      </div></section>
      <section class="summary-section"><div class="head"><h2>Pendientes</h2></div><div class="summary-grid">
        ${card(pendingReq.length,'Solicitudes pendientes',`${reqs.length} solicitudes en total`,'requests',pendingReq.length>0)}
        ${card(openInc.length,'Incidencias abiertas',`${incs.length} incidencias asociadas`,'incidents',openInc.length>0)}
        ${card(longstay.length,'Permanencias autorizadas','Solicitudes aprobadas','longstay')}
      </div></section>`;
    document.querySelectorAll('[data-owner-summary]').forEach(el=>el.onclick=()=>{
      const a=el.dataset.ownerSummary;
      if(a==='housing'){go('ownerHousing');return}
      if(a==='vehicles'){replaceViewUiState('ownerVehiclesTable',{});delete state.cache.ownerHousingFilter;delete state.cache.ownerNavPreset;delete state.cache.ownerVehiclePreset;go('ownerVehicles');return}
      if(a==='vehicles-slot'){replaceViewUiState('ownerVehiclesTable',{});delete state.cache.ownerHousingFilter;delete state.cache.ownerNavPreset;state.cache.ownerVehiclePreset={slot:'Con slot'};go('ownerVehicles');return}
      if(a==='vehicles-moto'){replaceViewUiState('ownerVehiclesTable',{});delete state.cache.ownerHousingFilter;delete state.cache.ownerNavPreset;state.cache.ownerVehiclePreset={vehicleClass:'Moto'};go('ownerVehicles');return}
      if(a==='requests'){replaceViewUiState('ownerRequestsTable',{});state.cache.ownerNavPreset={view:'ownerRequests',filter:'pending',type:'',period:'',group:'none'};go('ownerRequests');return}
      if(a==='incidents'){replaceViewUiState('ownerIncidentsTable',{});state.cache.ownerNavPreset={view:'ownerIncidents',filter:'open',type:'',period:'',group:'none'};go('ownerIncidents');return}
      if(a==='longstay'){replaceViewUiState('ownerRequestsTable',{});state.cache.ownerNavPreset={view:'ownerRequests',filter:'approved',type:'PERMANENCIA_PROLONGADA',period:'',group:'none'};go('ownerRequests')}
    });
  }catch(e){err(e)}
}
